FRAGMENTS = {
    "block-section-spells-4-1/item/0": "<<Banishment>> ^^(^^[[1|PHB]]^^)^^: одне з найпотужніших заклинань «пройди ряткидок або страждай»{{save-or-suck}} у грі з кількох причин. По-перше, це ряткидок Харизми, а дуже мало істот добре їх проходять. По-друге, багато потужних ворогів, як-от почвари, позапланові, тож їх легко прибрати одним заклинанням (хоча багато з них можуть накласти <<Plane Shift>>, щоб одразу повернутися, тож стережіться цього). Нарешті, накладання заклинання на вищому рівні дозволяє націлитися на додаткових істот, тож можна прибрати великі частини сутички на цілу хвилину, розібратися з усім, що пройшло початковий раунд вигнання, а потім підготуватися до того, що все інше повернеться, поки ваша група стоїть із заготовленими діями.",
    "block-section-spells-4-1/item/1": "<<Blight>> ^^(^^[[1|PHB]]^^)^^: недостатньо шкоди для слота заклинання такого рівня, а ряткидки Статури зазвичай високі.",
    "block-section-spells-4-1/item/2": "<<Charm Monster>> ^^(^^[[1|XGtE]]^^)^^: чудовий нелетальний спосіб упоратися з ворогами. Не вимагає, щоб ціль могла вас розуміти, але в іншому має ті самі ускладнення, що й <<Charm Person>>: ціль дружня лише до вас, а коли заклинання закінчується, вона знає, що її причарували.",
    "block-section-spells-4-1/item/3": "<<Confusion>> ^^(^^[[1|PHB]]^^)^^: я ненавиджу <<Confusion>> ще з 3-ї редакції. Воно непередбачуване, ненадійне й робить бій удвічі довшим, ніж зазвичай. Чудово, що воно діє по області, і ви, можливо, зможете змусити істот атакувати своїх союзників, але занадто багато точок відмови, щоб покладатися на нього як на надійний варіант.",
    "block-section-spells-4-1/item/4": "<<Dimension Door>> ^^(^^[[1|PHB]]^^)^^: зазвичай вистачає <<Misty Step|Туманного кроку>>, а <<Misty Step>> накладається бонусною дією.",
    "block-section-spells-4-1/item/5": "<<Dominate Beast>> ^^(^^[[1|PHB]]^^)^^: звірі зазвичай погано проходять ряткидки Мудрості, а кращого способу впоратися з потенційно ворожою істотою, ніж підкорити її, майже немає. Це заклинання може звести нанівець загрозу цілого типу істот, що вражає для заклинання такого рівня, а масштабування достатньо добре, щоб використання слота вищого рівня було привабливим, якщо ви зустрінете досить потужного звіра, якого реально протягнути крізь кілька зіткнень. Навіть якщо заклинання закінчиться передчасно, звірі не надто розумні, і вони можуть сприйняти істот, з якими ви змушували їх битися, як ворогів і продовжити бій з ними, або ж просто втекти, якщо їх поранено. Звірі рідко бʼються до останнього ХП, хіба що захищають своє потомство чи щось таке. Це тварини, а не фанатики. Утім, у чародіїв дуже мало місця для вивчення заклинань, а присвячувати відоме заклинання одному типу істот із максимальним ПН трохи вище 10 — ризикований вибір.",
    "block-section-spells-4-1/item/6": "<<Fire Shield>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): ви не хочете, щоб це заклинання вам знадобилося. Найкращий варіант — накласти його перед перетворенням чи чимось таким.",
    "block-section-spells-4-1/item/7": "<<Greater Invisibility>> ^^(^^[[1|PHB]]^^)^^: невидимість у 5e *справді* чудова, а бігати цілу хвилину, будучи майже невловимою ціллю, — величезна перевага. Якщо маєте, це чудовий кандидат для <<q:Extended Spell|Подовженого заклинання>>.",
    "block-section-spells-4-1/item/8": "<<Ice Storm>> ^^(^^[[1|PHB]]^^)^^: це заклинання жахливе. Два типи кубиків без очевидної причини. Два типи шкоди, що має сенс, але все одно дратує. Порівняйте з <<Erupting Earth|Виверженням землі>>: область дії <<Ice Storm|Крижаного шторму>> набагато більша (куб 20 фт. проти циліндра радіусом 20 фт.), але він завдає лише на 3 більше шкоди в середньому, а складна місцевість триває лише до кінця вашого наступного ходу, тож це майже безглуздо. Цього просто недостатньо, щоб виправдати те, що воно на рівень заклинання вище за <<Erupting Earth|Виверження землі>>.",
    "block-section-spells-4-1/item/9": "<<Polymorph>> ^^(^^[[1|PHB]]^^)^^: фантастичне й універсальне, але й дуже складне. Дивіться мій [[2|практичний гайд про «Перевтілення»]], щоб отримати детальні поради, як вичавити максимум із <<Polymorph>>.",
    "block-section-spells-4-1/item/10": "<<Raulothim's Psychic Lance>> ^^(^^[[1|FToD]]^^)^^: ситуативне за задумом. Шкода низька для заклинання такого рівня, особливо одноцільового, але шкода сама по собі — не причина, чому ви тут. Ряткидок — Інтелекту, а це зазвичай одні з найнижчих ряткидків навіть на дуже високих рівнях, і ціль при провалі стає Недієздатною, втрачаючи хід, тож попри те, що воно одноцільове з невиразною шкодою, це потужний інструмент проти поодиноких ворогів. Ще краще те, що якщо ви знаєте імʼя цілі (часто легко для іменованих антагоністів), можна накласти це без прямої видимості, ховаючись за стінами, в областях магічної темряви чи десь іще безпечно.",
    "block-section-spells-4-1/item/11": "<<Sickening Radiance>> ^^(^^[[1|XGtE]]^^)^^: це заклинання дуже легко недооцінити. Ефекти складні, а шкода 4к10 виглядає невражаючою, але нехай це вас не відлякує. Це чудове заклинання, щоб накласти в кімнату й зачинити двері, але навіть якщо це не варіант, це фантастичний спосіб упоратися з натовпами. З радіусом 30 футів можна вразити величезну кількість цілей, а з тривалістю 10 хвилин можна легко вбити будь-що, що надовго застрягло в області. Шкода 4к10 нормальна, а скасування невидимості чудове, але справжня принада — рівні Виснаження. Один рівень робить цілі менш здатними опиратися захопленню чи іншим заклинанням контролю натовпу на кшталт <<Maximilian's Earthen Grasp|Земляної хватки Максиміліана>> чи <<Web>>, які ваші союзники могли б накласти, щоб тримати ворогів в області. Два рівні зменшують швидкість цілей удвічі, ускладнюючи їм вихід із області. Три рівні накладають Перешкоду на кубику на ряткидки, тож їхній стан погіршуватиметься ще швидше. Якщо цілі якимось чином виживають до 5 рівнів Виснаження (вони вже зазнають 20к10 променевої шкоди, що багато), їхня швидкість падає до 0, тож вам більше не треба нічого робити, щоб запобігти втечі. Просто чекайте, поки вони досягнуть 6 рівнів Виснаження, що призводить до смерті, якщо сумарна шкода 24к10 променевої якимось чином їх не вбила. Лише врахуйте: це заклинання діє й на союзників, а якщо заклинання закінчується, рівні Виснаження знімаються миттєво.",
    "block-section-spells-4-1/item/12": "<<Spirit of Death>> ^^(^^[[1|BoMT]]^^)^^: заклинання виклику найнижчого рівня, доступне Чародієві. <<Summon Draconic Spirit>> буде кращим, щойно ви його отримаєте, але до того часу цього вистачить. Докладніше дивіться мій [[2|Практичний гайд із заклинань виклику]].",
    "block-section-spells-4-1/item/13": "<<Stoneskin>> ^^(^^[[1|PHB]]^^)^^: пристойний баф, але на цьому рівні магічні атаки поширені.",
    "block-section-spells-4-1/item/14": "<<Storm Sphere>> ^^(^^[[1|EEPC]]^^)^^: <<Sickening Radiance>> значно краще. Більша область дії, краща шкода, довша тривалість і кращий вторинний ефект. Навіть проти однієї цілі шкода <<Sickening Radiance|Нудотного сяйва>> (4к10, у середньому 22) краща за шкоду «Штормової хмари»{{Storm Cloud}} щодо однієї цілі (6к6, у середньому 21, враховуючи і шкоду по області, і блискавку).",
    "block-section-spells-4-1/item/15": "<<Vitriolic Sphere>> ^^(^^[[1|EEPC]]^^)^^: <<Fireball>>, але вищого рівня й з іншим типом шкоди. Та сама дальність, та сама область дії, той самий ряткидок, та сама школа. Але <<Vitriolic Sphere>> завдає кислотної шкоди, і замість того, щоб завдати всю шкоду одразу, частина її застосовується наприкінці наступного ходу цілей. Початкова шкода перевищує початкову шкоду <<Fireball|Вогнекулі>> на кілька очок, але сама по собі недостатньо, щоб виправдати різницю в рівні заклинання. Головне доповнення — ви завдаєте половину початкової шкоди наприкінці наступного ходу цілей. Це величезне підвищення шкоди, але воно застосовується лише якщо цілі провалили ряткидки, і, очевидно, має значення лише тоді, коли вони ще живі. Це чудове заклинання на початку бою, особливо якщо ви знаєте, що не вбʼєте цілі одним пострілом, але це також час, коли слід кидати заклинання на кшталт <<Sickening Radiance|Нудотного сяйва>> чи <<Wall of Fire|Стіни вогню>>, тож, можливо, використовуйте його як друге заклинання в сутичці.",
    "block-section-spells-4-1/item/16": "<<Wall of Fire>> ^^(^^[[1|PHB]]^^)^^: абсолютно фантастичний варіант контролю області.",
    "block-section-spells-4-1/item/17": "<<Watery Sphere>> ^^(^^[[1|EEPC]]^^)^^: схоже на <<Maximilian's Earthen Grasp|Земляну хватку Максиміліана>>, але ви можете переміщати сферу, і вона може вражати кілька цілей. Хоч це й чудові покращення, цілі роблять додаткові ряткидки наприкінці кожного ходу, не витрачаючи Дію, як мусять робити з <<Maximilian's Earthen Grasp|Земляною хваткою Максиміліана>> чи <<Web|Павутинням>>. Якби був вибір, я б скористався <<Web|Павутинням>>, перш ніж розглядати <<Watery Sphere|Водяну сферу>>.",
    "block-section-spells-5-1/item/0": "<<Animate objects>> ^^(^^[[1|PHB]]^^)^^: це заклинання складне, але коли воно працює, може бути надзвичайно ефективним; проте вам треба ретельно обирати обʼєкти, які ви оживляєте, щоб отримати від заклинання максимум, а розкіш вибору є не завжди. По-перше, уникайте будь-яких обʼєктів із ногами чи лапами, як-от столи й стільці; вибір обʼєктів, змушених літати, робить їх значно кориснішими. Далі треба зважити переваги обʼєктів різних розмірів. Більші обʼєкти займають більше місця й завдають більше шкоди за атаку, але численні малі атаки можуть завдати більше шкоди. Більші обʼєкти мають значно більше ХП, але значно гірший КБ. Середні істоти мають найгірший бонус атаки, а бонуси атаки покращуються, коли відходити від Середнього розміру в будь-який бік, змінюючи кількість шкоди, яку можна очікувати від кожної атаки. Зваживши всі фактори, у більшості випадків найкращий варіант — 10 крихітних обʼєктів. Вороги все одно не можуть заходити в їхній простір, а з 10 атаками загалом вони легко завдадуть більше шкоди, ніж будь-яка інша комбінація обʼєктів. За 10 раундів, по 10 атак за раунд, разом 100 атак, це 100к4+400 шкоди, у середньому 650. Очікуйте, що атаки влучатимуть приблизно в 50% випадків, але навіть тоді проти однієї цілі це в середньому до 325 шкоди, якщо ціль нічого з цим не зробить. Якщо оберете обʼєкти, що літають, вони легко оточать ворога, утримуючи його на місці в повітрі чи на землі. Щоправда, маючи лише по 20 ХП, вони вразливі до шкоди по області, але нескладно знайти інші заклинання, коли це проблема. А якщо не вдається знайти відповідних цілей, можна носити з собою мішок кинджалів, хлібин чи чогось іншого легкого й портативного.",
    "block-section-spells-5-1/item/1": "<<Bigby's Hand>> ^^(^^[[1|PHB]]^^)^^ (необовʼязкове): універсальна й ефективна проти різних ворогів. Шкода і від «Стиснутого кулака»{{Clenched Fist}}, і від «Стискаючої длані»{{Grasping Hand}} чудова й добре масштабується з рівнем заклинання. На цьому рівні у вас уже є багато способів упоратися з одиничними цілями, але зазвичай щойно ціль проходить ряткидок, вона вільна від ефекту. <<Bigby's Hand>> лишається на всю тривалість заклинання, дозволяючи вам постійно докучати цілі й переходити до нової, щойно попередня впаде. Оскільки це заклинання вміє багато чого в одному, це чудовий приклад заклинань, що вписуються в обмежену кількість відомих заклинань Чародія.",
    "block-section-spells-5-1/item/2": "<<Cloudkill>> ^^(^^[[1|PHB]]^^)^^: розроблене, щоб прокочуватися крізь армії, це заклинання важко використати в малих тактичних боях між групою шукачів пригод і купкою монстрів. Той простий факт, що ефект віддаляється від вас, ускладнює утримання заклинання на місці, а {{за правилами як написано|RAW}} незрозуміло, чи зупиняється ефект, коли натрапляє на тверду перешкоду, чи йому байдуже, і він котиться просто крізь суцільні обʼєкти на кшталт стін замку. За правилами як написано заклинання віддаляється від вас, а не від вашої початкової позиції під час накладання, тож ви можете керувати ефектом, бігаючи навколо нього, але з радіусом 20 футів вам може знадобитися більше за типову швидкість 25/30 фт., яку мають більшість гуманоїдних рас, якщо ви хочете робити щось більше за невеликі корективи напрямку хмари щораунду. Якщо хочете оббігти її повністю на протилежний бік хмари, треба пройти понад 60 футів (половина довжини кола діаметром 40 футів — приблизно 62,5 фута, але це не враховує розташування на сітці).",
    "block-section-spells-5-1/item/3": "<<Cone of Cold>> ^^(^^[[1|PHB]]^^)^^: попри більшу сумарну область дії, я вважаю, що воно гірше за <<Fireball|Вогнекулю>>. Навіть із конусом 60 футів у вас набагато менше гнучкості, ніж зі сферою радіусом 20 футів і дальністю 150 футів. 8к8 шкоди <<Cone of Cold|Конуса холоду>> лише трохи перевищує 8к8 шкоди <<Fireball|Вогнекулі>> (лише на 8 очок шкоди більше в середньому), а якщо накласти <<Fireball|Вогнекулю>> як заклинання 5-го рівня, <<Cone of Cold>> завдає лише на 1 очко шкоди більше в середньому.",
    "block-section-spells-5-1/item/4": "<<Control Winds>> ^^(^^[[1|EEPC]]^^)^^: створює незручності істотам, що покладаються на дальні атаки зброєю, і сповільнює ворогів, які намагаються рухатися в одному конкретному напрямку. Якщо вас турбують дальні атаки, накладайте <<Warding Wind>>. Якщо вас турбує, що вороги рухаються, розгляньте щось, що створює складну місцевість, як-от <<Erupting Earth>>. Якщо вас турбують літаючі вороги, накладайте <<Earthbind>> чи щось таке. Моя думка в тому, що є заклинання нижчих рівнів, які розвʼязують ті самі проблеми, що й <<Control Winds>>, і зазвичай роблять це краще.",
    "block-section-spells-5-1/item/5": "<<Creation>> ^^(^^[[1|PHB]]^^)^^: це заклинання обмежене максимальним обʼємом і вашою винахідливістю. Воно накладається цілу хвилину, тож у бою не стане в пригоді, але це чудовий утилітарний варіант. Куб 5 футів може здатися небагатьма, але цього досить для всіляких пустощів. Треба заблокувати коридор? А як щодо куба 5 футів із дерева чи каменю? Потрібна швидка пастка? Куля 5 футів із чогось важкого, скотіть її з пагорба. Бракує боєприпасів? Стріл вистачить, щоб наповнити куб 5 футів. Їжа? Куб 5 футів неживої рослинної матерії дуже схожий на їжу. Гарний одяг для вечірки? Найтонша бавовна. Треба підкупити когось, кого ви ненавидите? Самоцвіти тримаються лише 10 хвилин, тож робіть це швидко.",
    "block-section-spells-5-1/item/6": "<<Dominate Person>> ^^(^^[[1|PHB]]^^)^^: гуманоїди перестають бути поширеними ворогами після низьких рівнів, бо гуманоїди з високим ПН зазвичай є іменованими НІП{{NPC}} із передісторіями й подібним. Утім, кращого вимикача для гуманоїда за <<Dominate Person>> немає. Накладання заклинання на вищому рівні збільшує тривалість, дозволяючи протягти ціль крізь купу боїв. Проте шкода, якої зазнає істота, дає їй додаткові ряткидки, тож тримайте її подалі від небезпеки, доки не зможете зручно позбутися її з мінімальним ризиком для себе й союзників.",
    "block-section-spells-5-1/item/7": "<<Enervation>> ^^(^^[[1|PHB]]^^)^^: памʼятаєте <<Witch Bolt>> із самого 1-го рівня? <<Enervation>> — та сама ідея: ви влучаєте один раз, а потім витрачаєте кожну дію деякий час, завдаючи автоматичну шкоду. Це непогана концепція, але з лише 4к8 шкоди знадобиться надзвичайно довго, щоб убити будь-яку одиночну ціль, гідну слота заклинання 5-го рівня.",
    "block-section-spells-5-1/item/8": "<<Far Step>> ^^(^^[[1|XGtE]]^^)^^: телепортація справді приємна, але телепортуватися можна й <<Misty Step|Туманним кроком>>, що на 3 рівні заклинань нижче. Звісно, <<Far Step>> дозволяє пройти вдвічі далі, а телепортуватися 10 разів поспіль <<Misty Step|Туманним кроком>> без величезної кількості слотів заклинань не вийде, але ситуації, коли треба телепортуватися щораунду, мабуть, слід вирішувати польотом чи невидимістю.",
    "block-section-spells-5-1/item/9": "<<Hold Monster>> ^^(^^[[1|PHB]]^^)^^: чудовий приклад заклинання «пройди ряткидок або страждай»{{save-or-suck}}. За винятком нежиті, воно діє на будь-який тип істот, а параліч виводить істоту з бою майже так само, як її вбивство. Якщо у вас є союзник, що бʼється в ближньому бою, пошліть його добивати ближніми атаками. Автоматичні критичні влучання надто привабливі, щоб багато союзників ближнього бою їх проминули. Памʼятайте, що цілі роблять новий ряткидок наприкінці кожного свого ходу, тож треба діяти швидко, поки цілі ще під дією.",
    "block-section-spells-5-1/item/10": "<<Immolation>> ^^(^^[[1|EEPC]]^^)^^: проти однієї цілі з купою ХП і жахливими ряткидками Спритності це прохідне використання слота заклинання. Але це також повільний спосіб убити істоту з високим ПН, на яку ви зазвичай захочете це застосувати, а за той самий слот можна накласти <<Fireball|Вогнекулю>> і завдати 10к6 шкоди всьому в області, замість 8к6 одній цілі й *можливо* ще шкоди наступного раунду.",
    "block-section-spells-5-1/item/11": "<<Insect Plague>> ^^(^^[[1|PHB]]^^)^^: поєднуючи постійну шкоду зі складною місцевістю, <<Insect Plague>> — хороший варіант контролю області, до того ж ще кращий тим, що його можна розмістити в повітрі чи під водою, а не лише на землі. Проте радіус недостатньо великий, щоб не дати істоті втекти, якщо вона готова витратити Дію на Ривок, тож шукайте інші способи змусити істоту залишатися всередині сфери, як-от штовхання, підніжки чи накладання <<Wall of Stone|Стіни з каменю>>.",
    "block-section-spells-5-1/item/12": "<<Seeming>> ^^(^^[[1|PHB]]^^)^^: дуже ситуативне. У більшості кампаній воно не буде достатньо корисним, щоб ви присвятили йому одне зі своїх обмежених відомих заклинань.",
    "block-section-spells-5-1/item/13": "<<Skill Empowerment>> ^^(^^[[1|XGtE]]^^)^^: концептуально це чудове заклинання. До того часу, як ви зможете його накласти, бонус майстерності становитиме щонайменше +4, що математично перевищує середній приріст приблизно 3,5 від Переваги, яку ціль може отримати від <<Enhance Ability|Покращення здібності>>. Зі зростанням бонусу майстерності <<Skill Empowerment>> випереджає <<Enhance Ability>>, але це не обовʼязково дозволяє замінити <<Enhance Ability|Покращення здібності>>. <<Enhance Ability>> на 3 рівні заклинання нижче, має ту саму тривалість і застосовується до всіх перевірок однієї характеристики, а не лише до однієї навички. У ситуаціях на кшталт відправлення «обличчя» вашої групи на переговори вам може знадобитися ширше покриття, ніж одна навичка, щоб ціль могла користуватися різними навичками, а не змушувати її покладатися на ту, яку ви обрали для <<Skill Empowerment|Посилення навички>>. <<Skill Empowerment>> також не складається з наявною Експертизою{{Expertise}}, яку отримують і барди, і пройдисвіти, тож у багатьох групах ваш найімовірніший отримувач не матиме з нього користі. <<Skill Empowerment>> аж ніяк не погане заклинання, воно просто краще за <<Enhance Ability|Покращення здібності>> лише за певних обставин і для певних персонажів, а оскільки чародії отримують так мало відомих заклинань, вам справді потрібно вичавити максимум із кожного заклинання, яке ви знаєте.",
    "block-section-spells-5-1/item/14": "<<Summon Draconic Spirit>> ^^(^^[[1|FToD]]^^)^^: міцна літаюча викликана істота з кількома видами опору до шкоди, драконячий дух може знаходити невидимих ворогів, слугувати літаючим скакуном (хоча він розумний, тож не їдьте на ньому в ближній бій), а його атаки достатньо добрі, щоб завдавати чимало шкоди. Загалом це надійний, універсальний варіант виклику, хоч він може бути не таким смертоносним, як схожі заклинання. Звісно, універсальність має вирішальне значення для Чародія, тож отримати кілька застосувань від одного заклинання дуже привабливо.",
    "block-section-spells-5-1/item/15": "<<Synaptic Static>> ^^(^^[[1|XGtE]]^^)^^: почніть із <<Fireball|Вогнекулі>>. Відніміть 30 футів дальності, змініть тип шкоди на психічну й змініть ряткидок на Інтелект. Дуже мало істот добре роблять ряткидки Інтелекту, тож очікуйте, що більшість істот його провалять. 8к6 шкоди здається не вражаючим на цьому рівні заклинання, але віднімання к6 від кидків атаки й перевірок характеристик на цілу хвилину — значний дебаф. Це добрий варіант, щоб почати бій із великою кількістю ворогів-бійців, бо вони постраждають від дебафа найбільше, а більшість ворогів-бійців мають погані ряткидки Інтелекту.",
    "block-section-spells-5-1/item/16": "<<Telekinesis>> ^^(^^[[1|PHB]]^^)^^: фантастично універсальне. Самих лише утилітарних можливостей досить, щоб заклинання було того варте, а з тривалістю 10 хвилин на кожне накладання ви можете розвʼязати будь-які проблеми. Відчиняти двері, безпечно поводитися з пастками, переміщати перешкоди, діставати речі з-під диванів, допомагати з будівництвом чи розвʼязувати будь-які проблеми, що в реальному житті потребували б крана. Проти ворогів підняття їх у повітря й утримання Скутими може легко стати вироком, якщо у вас є інші союзники, які можуть добивати дальніми атаками або дістатися цілі польотом чи іншим способом. Оскільки ціль має лишатися в межах дальності заклинання, будьте обережні, утримуючи ціль прямо над своєю головою, щоб підняти її на максимальну висоту. Цілком нормально тримати її на висоті 30 футів над землею приблизно за 30 футів від вас по горизонталі. Ціль стає Поваленою, якщо отримує шкоду від падіння, що має сповільнити більшість істот настільки, щоб вони не могли вступити з вами в ближній бій без Ривка. Потім ви можете спробувати підняти її знову наступного ходу, бо заклинання триває 10 хвилин і його можна використовувати щоходу без обмежень.",
    "block-section-spells-5-1/item/17": "<<Teleportation Circle>> ^^(^^[[1|PHB]]^^)^^: ситуативне, але загалом одна з найбезпечніших опцій телепортації на великі відстані, особливо тому, що не має обмеження на кількість чи розмір уражених істот. Проте її корисність залежить від наявності зручних кіл телепортації у вашій кампанії. Якщо ваш Майстер не збирається робити такі кола телепортації доступними й корисними, шукайте деінде.",
    "block-section-spells-5-1/item/18": "<<Wall of Light>> ^^(^^[[1|XGtE]]^^)^^: шкода жахлива, але заклинання не для цього. Справжня користь — [[2|засліплювати]] все підряд. Істоти засліплюються, лише якщо вони в стіні, коли ви її створюєте, а істоти можуть проходити крізь стіну зовсім не уражені. Ряткидок — Статури, а ряткидки Статури зазвичай високі, і оскільки істоти роблять новий ряткидок щораунду, не можна розраховувати, що засліплення триватиме довше за раунд-два. Навіть можливість стріляти променями зі стіни розчаровує, бо вони завдають ті самі 4к8 шкоди й не накладають засліплення повторно.",
    "block-section-spells-5-1/item/19": "<<Wall of Stone>> ^^(^^[[1|PHB]]^^)^^: хоч воно точно не ефектне, важко переоцінити, наскільки ефективною може бути тверда камʼяна перешкода для розвʼязання проблем. Відгородивши частину ворогів у сутичці, можна перетворити одну складну сутичку на дві дуже легкі підряд. Вам треба підтримувати Концентрацію, але це також означає, що коли ви будете готові розібратися з тим, що тимчасово відгородили, можна просто припинити Концентрацію, а не ламати власну стіну. Поза життям шукача пригод це заклинання досить потужне, щоб ви могли непогано заробляти на будівництві лише ним. Якщо колись вирішите осісти, знайдіть місце з достатньою кількістю каменю, щоб закріпити заклинання, і збудуйте собі гарний камʼяний будинок.",
    "block-section-spells-6-1/item/0": "<<Arcane Gate>> ^^(^^[[1|PHB]]^^)^^: надто ситуативне, щоб його розглядати. Накладіть натомість <<Fly>> і нехай ваша група перелетить ті 500 фт.",
    "block-section-spells-6-1/item/1": "<<Chain Lightning>> ^^(^^[[1|PHB]]^^)^^: пристойна шкода на хорошій дальності. Звичайне заклинання зі шкодою по області, імовірно, завдасть більше сумарної шкоди, бо зачепить більше цілей, але це оминає головну принаду <<Chain Lightning|Ланцюгової блискавки>>. Вона хороша тим, що її можна накласти на людне місце, де можуть бути й ваші союзники, без жодного ризику дружнього вогню. Масштабування за рівнем заклинання додає цілі, а не шкоду, тож ви легко можете накласти її на такому рівні, щоб вразити рівно стільки цілей, скільки вважаєте за потрібне.",
    "block-section-spells-6-1/item/2": "<<Circle of Death>> ^^(^^[[1|PHB]]^^)^^: шкода 8к6 дорівнює шкоді <<Fireball|Вогнекулі>>, яка на три рівні заклинання нижча. Головні покращення — тип шкоди <<Circle of Death|Кола смерті>> та його справді величезна область дії з радіусом 60 футів. З такою великою областю й середовищем, багатим на цілі, ви легко завдасте більше сумарної шкоди, ніж <<Fireball|Вогнекулею>>. Масштабування теж на диво приємне: +2 кубики за рівень заклинання замість +1, як у більшості заклинань.",
    "block-section-spells-6-1/item/3": "<<Disintegrate>> ^^(^^[[1|PHB]]^^)^^: одне з найпотужніших у грі заклинань шкоди по одній цілі; шкода <<Disintegrate>> по одній цілі приблизно еквівалентна 21к6 (у середньому 75). Оскільки це ряткидок Спритності, спокушає використати його проти великих, громіздких ворогів, у яких зазвичай багато ХП, які треба зняти. В ідеалі таких істот краще брати заклинанням типу «пройди ряткидок або страждай»{{save-or-suck}}, але такі речі, як «Легендарний опір»{{Legendary Resistance}}, часом це ускладнюють. Також <<Disintegrate>> можна використати, щоб прибрати проблемні перешкоди на кшталт <<Wall of Force|стін енергії>> (чи стін із будь-чого іншого), що дозволяє, наприклад, обвалити споруди або проломити стіни, щоб заскочити ворогів по той бік зненацька.",
    "block-section-spells-6-1/item/4": "<<Eyebite>> ^^(^^[[1|PHB]]^^)^^: якщо ви накладете його, не чекайте, що зможете робити щось інше до кінця сутички. Заклинання типу «пройди ряткидок або страждай»{{save-or-suck}}, що присипляє цілі щоразу, важко перевершити, а те, що це можна робити кожного ходу, — просто чудово. Звісно, цілі лишаються сплячими лише до кінця заклинання, але цього цілком достатньо, щоб хтось інший із вашої групи підійшов і завдав гарантованого критичного влучання. Коли ціль прокинеться від отриманої шкоди, вона все ще буде Поваленою, а на вашому наступному ході ви знову можете її присипити.",
    "block-section-spells-6-1/item/5": "<<Flesh to Stone>> ^^(^^[[1|PHB]]^^)^^: «пройди ряткидок або страждай»{{save-or-suck}} по одній цілі, але цілі роблять кілька ряткидків, а ряткидки Статури зазвичай високі, тож не можна розраховувати, що це спрацює надійно. Навіть якщо ціль таки піддасться заклинанню, це займе *щонайменше* три раунди. Можливо, вам вдасться змусити це працювати, поєднуючи такі речі, як <<Mind Spike>>, щоб погіршити ряткидок цілі, і <<q:Twinned Spell|Спарене заклинання>>, щоб вражати кілька цілей.",
    "block-section-spells-6-1/item/6": "<<Fizban's Platinum Shield>> ^^(^^[[1|FToD]]^^)^^: фантастично універсальний, це чудовий захист від поширених ефектів шкоди по області, як-от зброя дихання й <<Fireball|вогнекулі>>. Памʼятайте, що укриття на половину дає бонус +2 і до КБ, і до ряткидків Спритності. Час накладання — бонусна дія — зручний: його легко вписати в хід разом із замовлянням. Для себе <<Absorb Elements>> може бути простішим вибором, бо воно значно нижчого рівня й витрачає лише вашу Реакцію, але можливість поділитися цим заклинанням (особливо зі <<q:Twinned Spell|Спареним заклинанням>>) може зробити його привабливішим.",
    "block-section-spells-6-1/item/7": "<<Globe of Invulnerability>> ^^(^^[[1|PHB]]^^)^^: вона знадобиться вам лише зрідка, але проти ворожих заклинателів їй немає заміни. Щойно вона діє, вороги навіть не можуть накласти <<Counterspell>>, бо воно націлюється на вас, а ви всередині сфери. Вони могли б накласти <<Counterspell>> на рівні заклинання, достатньо високому, щоб пробити вашу сферу, але їм доведеться вгадувати, який рівень заклинання використати, і витрачати для цього слоти заклинань дуже високих рівнів. Навіть у боях із заклинателями, які можуть накладати заклинання зі слотів 9-го рівня, ви можете накласти її як заклинання 9-го рівня й використати <<Counterspell|Контрчари>> проти будь-яких заклинань 9-го рівня, які вони накладуть (хоча доведеться кинути перевірку характеристики й сподіватися на краще). Це заклинання також унікально калічить чорнокнижників, бо їхні слоти заклинань обмежені 5-м рівнем, а вони сильно покладаються на замовляння. Вони все ще можуть користуватися «Містичним арканумом»{{Mystic Arcanum}}, якщо ви не накладете <<Globe of Invulnerability|Сферу невразливості>> на вищому рівні, але таких заклинань у них щонайбільше 4, а у вас повно слотів заклинань для <<Counterspell|Контрчарів>>. Попри всі ці сильні сторони, треба лишатися обережним: 1 хвилина — це недовго, а вороги все ще можуть безперешкодно заходити в сферу й атакувати вас упритул. Тримайте союзників усередині сфери, щоб захистити і їх самих, і вас, і остерігайтеся атак, що не є заклинаннями, на кшталт зброї дихання та гострих палиць.",
    "block-section-spells-6-1/item/8": "<<Investiture of Flame>> ^^(^^[[1|EEPC]]^^)^^: ви ніколи не повинні лишатися настільки близько до ворогів і настільки довго, щоб це був добрий вибір.",
    "block-section-spells-6-1/item/9": "<<Investiture of Ice>> ^^(^^[[1|EEPC]]^^)^^: ви ніколи не повинні лишатися настільки близько до ворогів і настільки довго, щоб це був добрий вибір.",
    "block-section-spells-6-1/item/10": "<<Investiture of Stone>> ^^(^^[[1|EEPC]]^^)^^: ви ніколи не повинні лишатися настільки близько до ворогів і настільки довго, щоб це був добрий вибір.",
    "block-section-spells-6-1/item/11": "<<Investiture of Wind>> ^^(^^[[1|EEPC]]^^)^^: поєднайте найважливіші частини <<Fly|Польоту>> і <<Warding Wind|Захисного вітру>> — і матимете змогу відштовхувати істот на відстані, чим ви, можливо, скористаєтеся раз чи двічі. Імовірно, недостатньо добре для цього рівня заклинання, але потенційно цікаво.",
    "block-section-spells-6-1/item/12": "<<Mass Suggestion>> ^^(^^[[1|PHB]]^^)^^: ситуативно, але потенційно дуже ефективно. На відміну від <<Suggestion>>, вам не потрібно підтримувати Концентрацію, а базова тривалість <<Mass Suggestion|Масового навіювання>> утричі більша за тривалість <<Suggestion>>, з можливістю подовжити її слотами вищих рівнів. Якщо ви мали добрі результати з <<Suggestion|Навіюванням>>, подумайте про заміну його на <<Mass Suggestion>>.",
    "block-section-spells-6-1/item/13": "<<Mental Prison>> ^^(^^[[1|XGtE]]^^)^^: чудовий «пройди ряткидок або страждай»{{save-or-suck}} по одній цілі. Майже ніхто не має добрих ряткидків Інтелекту, тож це міцний основний вибір. Ціль не бачить і не чує нічого поза ментальною вʼязницею, а ви можете спокійно розстрілювати її, поки вона Скована. Це не так обмежує, як стан Паралізований від <<Hold Monster>>, але значно надійніше, і ціль не робить додаткових ряткидків щораунду. Формально ціль усе ще може бачити й чути, але лише всередині ілюзії, а більшість наступальних заклинань вимагає прямої видимості, тож найбільше, що можуть зробити більшість ворогів, — накласти на себе баф або, можливо, стріляти наосліп крізь ілюзію.",
    "block-section-spells-6-1/item/14": "<<Move Earth>> ^^(^^[[1|PHB]]^^)^^: поза пригодами це заклинання було б надзвичайно корисним, особливо в поєднанні з <<Stone Shape|Формою каменю>>. Але для авантюриста його користь дуже обмежена.",
    "block-section-spells-6-1/item/15": "<<Otiluke's Freezing Sphere>> ^^(^^[[1|PHB]]^^)^^: зі шкодою 10к6 вона перевершує <<Fireball|Вогнекулю>> лише на 2 кубики (що сумно, бо <<Fireball>> на три рівні нижча), але має вдвічі більшу дальність і величезний радіус 60 футів. Оскільки призначення заклинання — насамперед миттєвий вибух шкоди по області, вибрати і його, і <<Fireball|Вогнекулю>> важко виправдати, а <<Fireball>> вигідніша, хіба що ви справді хочете роздавати союзникам заморожені кулі, щоб вони їх кидали.",
    "block-section-spells-6-1/item/16": "<<Scatter>> ^^(^^[[1|XGtE]]^^)^^: телепортуйте союзників ближнього бою в ближній бій, а союзників дальнього бою — з нього. Якщо лишаться цілі, використайте його, щоб телепортувати ворогів у якесь неприємне місце, наприклад у діючий ефект по області.",
    "block-section-spells-6-1/item/17": "<<Sunbeam>> ^^(^^[[1|PHB]]^^)^^: ряткидки Статури зазвичай високі, а лінію важко націлити так, щоб вразити більше однієї цілі. Є чимало кращих заклинань, на які можна витратити вашу Концентрацію на 1-хвилинну тривалість <<Sunbeam|Сонячного променя>>. Попри це обмеження, у Чародія є унікальна синергія з <<Sunbeam|Сонячним променем>>: завдяки <<q:Quickened Spell|Пришвидшеному заклинанню>> ви можете обійти обмеження в одне заклинання з рівнем за хід і швидко завдати купу шкоди. На 1-му ході накладіть <<Sunbeam>> (за бажанням можна пришвидшити його, щоб активувати двічі за один хід), а на наступних ходах ви можете накладати заклинання з рівнем бонусною дією завдяки «Пришвидшеному заклинанню», а Дію однаково витратити на активацію <<Sunbeam|Сонячного променя>>. Якщо вдасться вишикувати двох або більше ворогів на кількох ходах поспіль, так можна завдати величезну кількість шкоди.",
    "block-section-spells-6-1/item/18": "<<Tasha's Otherworldly Guise>> ^^(^^[[1|TCoE]]^^)^^ (необовʼязкове): кілька корисних бафів, зокрема політ і бонус до КБ, поряд з іншими більш ситуативними перевагами. Ви також отримуєте еквівалент «Додаткової атаки»{{Extra Attack}}. Це дивна перевага, бо більшості чародіїв нема чого робити зі зброєю. Тож найбільша перевага заклинання — політ і захисні бафи за часу накладання бонусною дією.",
    "block-section-spells-6-1/item/19": "<<True Seeing>> ^^(^^[[1|PHB]]^^)^^: ви не завжди хочете, щоб це діяло, але завжди хочете мати це напоготові. Протягом 1 години ви бачите крізь ілюзії та невидимість, фактично скасовуючи їх, а також бачите в Ефірному плані, тож помічаєте істот, що користуються <<Blink|Мерехтінням>> чи самі ходять Ефірним планом, як-от фазові павуки. Однак ви бачите лише на 120 футів, тож захищені не цілком. Невидимі істоти можуть тримати безпечну дистанцію, спостерігаючи за вами й навіть атакуючи вас, якщо для цього вистачає місця.",
    "block-section-spells-7-1/item/0": "<<Crown of Stars>> ^^(^^[[1|XGtE]]^^)^^: багато в чому схоже на <<Melf's Minute Meteors>>. <<Crown of Stars>> завдає значно більше шкоди за заряд (2к6 проти 4к12), але вражає лише одну ціль, а не мізерно малу область. Накладення <<Melf's Minute Meteors|Мельфових маленьких метеорів>> на вищому рівні дає вам загалом 14 метеорів і сумарно 28к6 шкоди (звісно, якщо ніхто не пройде ряткидок). <<Crown of Stars>> на тому самому рівні заклинання завдасть сумарно 28к12 шкоди, і доставить її значно швидше й значно меншою кількістю снарядів. Навіть якщо ігнорувати можливість критичних влучань від <<Crown of Stars|Корони зірок>>, вам усе одно довелося б вражати двох цілей кожним метеором <<Melf's Minute Meteors|Мельфових маленьких метеорів>>, щоб перевищити середню шкоду <<Crown of Stars|Корони зірок>>, а зважаючи на те, що це треба зробити 14 разів за 10 хвилин, це здається вкрай малоймовірним. Якщо ви покладалися на маленькі метеори, час переходити на кращий варіант. <<Crown of Stars>> не вимагає Концентрації, а з тривалістю в 1 годину ви отримуєте вшестеро більше часу, щоб витратити вдвічі менше снарядів. Це може бути не основним вибором для кожного заклинателя, але якщо ви можете підготувати це перед тим, як зайти в бій, і якщо зазвичай мало користуєтеся своєю бонусною дією, це чудове підсилення вашої шкоди.",
    "block-section-spells-7-1/item/1": "<<Delayed Blast Fireball>> ^^(^^[[1|PHB]]^^)^^: ситуативно й потенційно дуже важко застосувати на повну, але якщо вдасться, максимум 22к6 шкоди (у середньому 77) важко перевершити. Найскладніше — заряджати його цілу хвилину, поки вороги нічого не роблять, щоб вам завадити, чи то зриваючи вашу Концентрацію, чи втручаючись у вогнекулю. Подекуди може виявитися, що бій уже закінчився або всі бійці перемістилися, перш ніж ви зможете спровокувати ефект. Імовірно, найкращий варіант — щоб союзник, винятково вправний у ряткидках Спритності (особливо якщо він може мати Перевагу на кубику та/або інший баф на кшталт <<Resistance|Опору>> чи <<Bless>>), схопив вогнекулю й відкинув її щонайбільше на 40 футів, щоб спровокувати вибух у ефективнішому місці перед самим закінченням 1-хвилинної тривалості заклинання. Якщо вдасться це провернути на початку бою, 22к6 шкоди — чудовий спосіб представитися.",
    "block-section-spells-7-1/item/2": "<<Draconic Transformation>> ^^(^^[[1|FToD]]^^)^^: сліпозір, політ і зброя дихання, яку можна використати і відразу, і бонусною дією на наступних ходах. Шкода зброї дихання така сама, як у <<Fireball|Вогнекулі>>, тож ви кожного ходу бонусною дією завдаєте стільки шкоди, як від вогнекулі 3-го рівня. Єдина проблема в тому, що це краще використовувати на початку бою, де заклинання контролю області чи контролю натовпу були б одразу впливовішими. Найкраще накласти це перед самим початком бою або в хід, коли ви й так збиралися накласти замовляння.",
    "block-section-spells-7-1/item/3": "<<Dream of the Blue Veil>> ^^(^^[[1|TCoE]]^^)^^ (необовʼязкове): це більше сюжетний прийом, ніж заклинання. Не вивчайте його, якщо вам не скаже Майстер.",
    "block-section-spells-7-1/item/4": "<<Etherealness>> ^^(^^[[1|PHB]]^^)^^: надзвичайно ефективний варіант розвідки/втечі. Якщо ви не бʼєтеся з ефірними ворогами, ви недоторкані. Ви бачите й чуєте Матеріальний план (хай і на обмеженій відстані), що дозволяє особисто шпигувати за іншими істотами без їхнього відома. Заклинання триває 8 годин — цього вистачає на багато справ, потенційно включно з Довгим відпочинком.",
    "block-section-spells-7-1/item/5": "<<Finger of Death>> ^^(^^[[1|PHB]]^^)^^: завдає менше шкоди, ніж <<Disintegrate>> (яке на рівень заклинання нижче), і має ряткидок, якому вороги частіше опираються. Єдина причина накладати це замість <<Disintegrate>> — безкоштовний зомбі, якщо ви вбʼєте ціль, а якщо вам просто потрібні зомбі, це повільний спосіб збудувати армію, навіть якщо цілі назавжди під вашим контролем.",
    "block-section-spells-7-1/item/6": "<<Fire Storm>> ^^(^^[[1|PHB]]^^)^^: <<Fireball>>, накладена на тому самому рівні, завдає трохи більше шкоди (12к6, у середньому 42 проти 7к10, у середньому 35). Головна перевага <<Fire Storm|Вогняного шторму>> над <<Fireball|Вогнекулею>> у тому, що ви можете вирізати область дії так, щоб не зачепити своїх союзників. Але навіть тоді <<Chain Lightning>> завдає більше шкоди (10к8, у середньому 45) і вражає чотири цілі, тож у багатьох сутичках це кращий варіант. <<Fire Storm>> справді сяє проти великих натовпів, де 10 кубів по 10 футів можуть накрити велику кількість ворогів, не зачепивши ваших союзників. Але такі ситуації рідкісні, а в багатьох випадках варіанти нижчого рівня на кшталт <<Circle of Death|Кола смерті>> можуть бути дуже ефективними й вразити більше цілей, якщо вам не страшно зачепити своїх союзників.",
    "block-section-spells-7-1/item/7": "<<Plane Shift>> ^^(^^[[1|PHB]]^^)^^: не зовсім такий простий у використанні, як <<Teleport>>, але має певні переваги. По-перше й найочевидніше, <<Teleport>> не може перенести вас на інші плани. По-друге, <<Teleport>> не можна використати наступально. На жаль, <<Plane Shift>> дуже важко використати в бою, бо інші істоти мають тримати одна одну за руки в колі. Також не можна потрапити безпосередньо в місця на тому самому плані, тож, можливо, доведеться знайти зручне місце для зупинки по дорозі. Обирайте гостинне, безпечне місце, в ідеалі або безлюдне, або населене істотами, яких ви знаєте й які до вас дружні.",
    "block-section-spells-7-1/item/8": "<<Power Word Pain>> ^^(^^[[1|PHB]]^^)^^: на це важко покладатися, якщо у вас немає союзника, який зможе продовжити заклинанням типу «пройди ряткидок або страждай»{{save-or-suck}} до наступного ходу цілі. Але в такому разі, можливо, ви матимете кращі результати, якщо почнете із заклинання «пройди ряткидок або страждай», хіба що ціль має «Легендарний опір»{{Legendary Resistance}}.",
    "block-section-spells-7-1/item/9": "<<Prismatic Spray>> ^^(^^[[1|PHB]]^^)^^: непередбачувано. Область дії чудова, а ефекти 6, 7 і 8 — усі чудові (будь-які два промені були б вражаючими), але заклинання непередбачуване, а я завжди неохоче рекомендую непередбачувані заклинання, бо непередбачуване часто означає ненадійне. Якщо вам раніше подобався <<Cone of Cold>> і ви хочете покращення, тут я бачу можливість.",
    "block-section-spells-7-1/item/10": "<<Reverse Gravity>> ^^(^^[[1|PHB]]^^)^^: фантастично, бо їй так важко опиратися. Навіть якщо цілі за щось вхопляться, їм усе одно треба триматися за це протягом усієї дії заклинання. Цілі, які не можуть ні за що вхопитися, здебільшого безпорадні, якщо не вміють літати, а хоч політ і поширений на цьому рівні, він аж ніяк не універсальний. Тараск, наприклад, здебільшого безпорадний проти цього заклинання.",
    "block-section-spells-7-1/item/11": "<<Teleport>> ^^(^^[[1|PHB]]^^)^^: з дальністю 10 футів і до 8 цілей ви легко телепортуєте всю свою групу, а без потреби триматися за руки в колі часто можна врятувати всю групу посеред бою без особливих труднощів. Проте в <<Teleport|Телепорті>> складна механіка, повʼязана з тим, наскільки добре ви знаєте місце призначення, і часто є ймовірність невдачі. Обовʼязково прихоплюйте сувенір із нових місць, щоб за потреби легко повернутися без ризику невдачі.",
    "block-section-spells-7-1/item/12": "<<Whirlwind>> ^^(^^[[1|EEPC]]^^)^^: якщо хочете шкоди, шукайте буквально будь-де інде. Якщо хочете підняти ворогів над підлогою, накладайте <<Reverse Gravity|Обернену гравітацію>>, бо вона значно ефективніша й надійніша.",
    "block-section-spells-8-1/item/0": "<<Abi-Dalzim's Horrid Wilting>> ^^(^^[[1|EEPC]]^^)^^: для такої вигадливої назви це заклинання напрочуд просте. Окрім того, як воно взаємодіє з деякими типами істот, це по суті <<Fireball|вогнекуля>> з іншою областю дії та кращою шкодою. <<Sunburst>> завдає приблизно стільки ж шкоди й [[2|засліплює]] цілі в області з удвічі більшим радіусом, тож я вважаю його значно кращим варіантом.",
    "block-section-spells-8-1/item/1": "<<Demiplane>> ^^(^^[[1|PHB]]^^)^^: справді круте заклинання, але навряд чи воно настільки корисне, щоб вивчити його назавжди.",
    "block-section-spells-8-1/item/2": "<<Dominate Monster>> ^^(^^[[1|PHB]]^^)^^: імовірно, найкраще заклинання типу «пройди ряткидок або страждай»{{save-or-suck}} у грі. З досконалим контролем над істотою на такий довгий час можна зробити багато. Використання цілі як підданого в бою, очевидно, спокушає, але ціль повторює ряткидок щоразу, коли отримує шкоду, тож будьте дуже обережні, якщо вирішите так робити.",
    "block-section-spells-8-1/item/3": "<<Earthquake>> ^^(^^[[1|PHB]]^^)^^: потужне заклинання контролю області, але вам не варто бути в радіусі 100 футів, а оскільки ви не контролюєте появу розломів, також не можна ризикувати розміщувати його з ворогами біля країв. Також не варто ризикувати використовувати його всередині чи в області, де сусідня споруда може впасти на вас. Тож вам треба центрувати ефект на цілях якомога точніше, бути на безпечній відстані від центральної точки, а також вам може знадобитися додатковий простір, щоб уникнути падіння споруд. Якщо ви можете дотриматися цих умов і все одно помістити заклинання куди треба (розгляньте політ), воно може зрівняти з землею місто однією Дією. Концентрація на заклинанні нічого не дає, крім підтримки складної місцевості, а це означає, що ви отримуєте майже всі ефекти заклинання за один хід, тож сміливо припиняйте Концентрацію й переходьте до чогось іншого.",
    "block-section-spells-8-1/item/4": "<<Incendiary Cloud>> ^^(^^[[1|PHB]]^^)^^: по суті це <<Cloudkill>> з купою покращень. Шкода рівно вдвічі більша, тип шкоди кращий (хоча вогонь усе ще один із типів шкоди, яким найчастіше опираються), а ряткидки Спритності ефективніші за ряткидки Статури. Шкода приблизно відповідає <<Fireball|Вогнекулі>>, накладеній на тому самому рівні (у середньому 45 проти 45,5 у <<Fireball|Вогнекулі>>), і застосовується кожного раунду протягом усієї 1-хвилинної тривалості. Проте вона все ще має деякі з найбільших проблем <<Cloudkill|Вбивчої хмари>>. По-перше, шкода застосовується під час накладання заклинання, але повторно застосовується до істот усередині ефекту лише тоді, коли вони закінчують хід у хмарі. З радіусом 20 футів більшість істот легко можуть вийти з хмари. Заклинання також примусово переміщується на 10 футів щораунду, а текст, що пояснює, як це працює, абсолютно безглуздий. За буквою правил ви обираєте напрямок, але можете обрати лише те, що воно рухається прямо від вас. На щастя, Джереми Кроуфорд розʼяснив, що [[2|ви обираєте його напрямок]], тож ви можете змусити хмару повільно перекочуватися туди-сюди на тому самому невеликому майданчику, якщо захочете.",
    "block-section-spells-8-1/item/5": "<<Power Word Stun>> ^^(^^[[1|PHB]]^^)^^: ризикувати, граючи на поточних ХП істоти, важко, особливо тому, що на цьому рівні у вас так мало слотів заклинань, але якщо ви зможете підгадати це по пораненому ворогу (або ворогу з низьким максимумом ХП, як у багатьох заклинателів), воно може вивести його з сутички достатньо надовго, щоб ви перемогли здебільшого без опору.",
    "block-section-spells-8-1/item/6": "<<Sunburst>> ^^(^^[[1|PHB]]^^)^^: уявіть <<Fireball|вогнекулю>> з утричі більшим радіусом, що ще й [[2|засліплює]] цілі. Цілі роблять ряткидок Статури кожного ходу, щоб зняти засліплення, тож не варто розраховувати, що воно триватиме довго, але ряткидок робиться наприкінці їхніх ходів, тож вони проведуть засліпленими щонайменше один хід, якщо провалять початковий ряткидок, і цього може вистачити, щоб вирішити результат сутички.",
    "block-section-spells-9-1/item/0": "<<Blade of Disaster>>[[1|ID:RotF / TCoE]] (необовʼязкове): майже в кожній ситуації <<Meteor Swarm>> чи <<Psychic Scream>> — кращий варіант шкоди, але в довгих боях із потужними одиночними ворогами сумарна шкода від <<Blade of Disaster|Клинка катастрофи>> буде ефективнішою. Також є додаткова перевага: воно не вбиває вашу групу в тісних приміщеннях.",
    "block-section-spells-9-1/item/1": "<<Gate>> ^^(^^[[1|PHB]]^^)^^: це заклинання можна використовувати кількома способами, два з яких були задумані, коли воно створювалося.",
    "block-section-spells-9-1/item/2": "Подорож на інший план: найпростіший варіант — ви відчиняєте двері й проходите на інший план, залишаючи браму відчиненою до хвилини, щоб ще хтось міг пройти в будь-якому напрямку.",
    "block-section-spells-9-1/item/3": "Виклик істоти: якщо ви знаєте імʼя істоти на іншому плані, можете притягнути її (потенційно проти її волі й без ряткидка) до свого розташування. Це легко використати зловживанням: перейдіть на план, де, як ви знаєте, її немає (кишенькові виміри чудово для цього підходять, але планів так багато, що випадково опинитися на тому самому важко), а потім примусово викличте її. Ви могли б викликати свого найбільшого антагоніста, витративши купу часу на розставлення пасток, бафів і підготовлених дій, а потім дозволити вашій групі втоптати його в бруд. Якщо ви особливо кмітливі, можете використати <<Astral Projection|Астральну проєкцію>>, щоб битися з тим, кого викликаєте, у проєкції, тож якщо щось піде не так, ви насправді не помрете й зможете спробувати пізніше. Я думаю, що задум цієї функції був у тому, щоб викликати союзника, який допоможе вам у бою, але я вважаю, що моя ідея корисніша.",
    "block-section-spells-9-1/item/4": "Однобічне укриття: увійти в портал можна лише спереду, але незрозуміло, як виглядає його зворотний бік і як він працює. Він не описаний як твердий, тож цілком можливо, що крізь нього можна стріляти ззаду, тоді як снаряди спереду пролітають у портал. Не уявляю, щоб крізь портал можна було щось бачити, тож це може бути складно, але, можливо, це можливо. Уточніть у свого Майстра.",
    "block-section-spells-9-1/item/5": "Магічний злив: ось-ось утопитеся? Ось-ось вас накриє потік магми чи каміння, що падає? Відкрийте браму буквально будь-куди й нехай ця неприємна субстанція насолоджується вічністю, пливучи в Лімбі чи будь-де, де вона вам не завадить. Мультивсесвіт — ваше сміттєзвалище.",
    "block-section-spells-9-1/item/6": "<<Mass Polymorph>> ^^(^^[[1|XGtE]]^^)^^: ви жертвуєте абсолютною силою <<True Polymorph|Істинного перевтілення>> заради можливості вплинути щонайбільше на 10 істот. Правила щодо істот без ПН (вашої групи) написано так, що це стає справді непривабливим порівняно з <<True Polymorph|Істинним перевтіленням>>. Порівняно з перетворенням одного союзника на дракона з ПН 17+, перетворення до 10 ваших союзників на тиранозаврів (тиранозаврусів? тиранозаври?) просто не таке ефективне, навіть якщо фраза «Я перетворюю нас і наших коней на тиранозаврів» — одна з найкрутіших речей, які я можу придумати сказати під час гри. На жаль, цілі набувають розумових характеристик звіра, тож перетворення вашої групи авантюристів на зубастих ящірок може насправді зробити їх слабшими. Заклинання можна використати наступально, а цілі не роблять ряткидків, окрім першого, тож перетворіть своїх ворогів на слимаків чи щось подібне й закиньте їх на Стихійний план Вогню чи в інше не менш неприємне місце.",
    "block-section-spells-9-1/item/7": "<<Meteor Swarm>> ^^(^^[[1|PHB]]^^)^^: найкраще заклинання шкоди по області: 40к6 достатньо, щоб зрівняти з землею більшість будівель, а з радіусом 40 футів і приголомшливою дальністю 1 миля ви можете облягати міста з безпечної відстані. У заклинанні сказано, що воно шкодить лише істотам, але за словами Джереми Кроуфорда, [[2|«Рій метеорів» шкодить і предметам]]. Найбільша проблема заклинання в тому, що воно робить лише шкоду. Хоч шкода чудова, а заклинання її завдає чимало, якщо ви не вбʼєте цілі відразу, вам усе одно доведеться мати з ними справу в наступному раунді. Також памʼятайте, що цілі можуть зазнати впливу лише раз, тож не морочтеся перекриттям сфер.",
    "block-section-spells-9-1/item/8": "<<Power Word Kill>> ^^(^^[[1|PHB]]^^)^^: просто вбиває ціль, а її єдиний спосіб опиратися — мати понад 100 ХП (або <<Counterspell>> чи щось таке). На жаль, без купи метагейму дуже важко дізнатися, чи в цілі менше 100 ХП. А навіть якщо так, <<Power Word Kill>> не обовʼязково ваш найкращий варіант. <<Meteor Swarm>> завдає в середньому 140 шкоди, тож якщо в цілі менше 100 ХП, їй і так непереливки. Щоправда, <<Meteor Swarm|Роєм метеорів>> не вдариш по комусь за обіднім столом, але я думаю, що <<Meteor Swarm>> буде надійнішим у більшості ситуацій, коли треба обірвати життя за лічені секунди.",
    "block-section-spells-9-1/item/9": "<<Psychic Scream>> ^^(^^[[1|XGtE]]^^)^^: до 10 істот у межах 90 футів від вас у будь-якому напрямку. Ряткидки Інтелекту в середньому найслабші, навіть для монстрів із високим ПН, тож у багатьох випадках можна Приголомшити ворогів і тримати їх приголомшеними неймовірно довго. Ефект приголомшення не має тривалості, тож вороги зі слабким Інтелектом можуть бути *приголомшені назавжди*. Шкода пристойна, але це абсолютно другорядна річ порівняно з ефектом приголомшення.",
    "block-section-spells-9-1/item/10": "<<Time Stop>> ^^(^^[[1|PHB]]^^)^^: 1к4+1 ходів поспіль дозволяють багато зробити, щоб звести сутичку нанівець. Якщо хочете бути особливо підлим, можна підкинути <<Delayed Blast Fireball|Вогнекулю відкладеної дії>>, відгородити область чимось на кшталт <<Stone Shape|Форми каменю>>, а потім телепортуватися геть.",
    "block-section-spells-9-1/item/11": "<<Wish>> ^^(^^[[1|PHB]]^^)^^: найкраще заклинання в грі, але й найскладніше. Воно буквально настільки добре, що я не оцінюватиму жодне інше заклинання 9-го рівня синім, бо ніщо інше не може з ним конкурувати. Більше допомоги щодо <<Wish>> дивіться в моєму [[2|практичному гайді про «Бажання»]].",
}

FRAGMENTS = {key: refs.pair_label_marker(value) for key, value in refs.expand_all(FRAGMENTS).items()}
